const TITLE_REQUEST_MARKER = "__BELEIDSKOMPAS_TITLE_REQUEST__";
const TITLE_PREFIX = "Beleidskompas - ";
const REQUEST_META_LABEL = "beleidskompas-request";
const STEP_ROUTES = {"stap1":"beleidskompas-step-stap1","stap2":"beleidskompas-step-stap2","stap3":"beleidskompas-step-stap3","stap4":"beleidskompas-step-stap4"};
const DEFAULT_STEP_ID = "stap1";
const UNKNOWN_STEP_TEXT = "Beleidskompas kon niet bepalen voor welke stap dit bericht is en heeft het daarom niet beantwoord. Stel je vraag opnieuw vanaf de Beleidskompas-pagina, met een stap gekozen.";
const STORE_MISSING_TEXT = "Beleidskompas kan zijn opslag niet gebruiken en heeft dit bericht daarom niet beantwoord. Meld dit bij de beheerder.";
const STORE_FAILED_TEXT = "De opslag van Beleidskompas gaf een fout. Dit bericht is daarom niet beantwoord; probeer het later opnieuw.";
const STORE_WARNING_TEXT = "Let op: de opslag van Beleidskompas gaf een fout. Dit antwoord is mogelijk niet bewaard.";
const STEP_SUMMARIES = [
  {
    "id": "stap1",
    "nr": 1,
    "title": "Publiek en provinciaal belang",
    "role": "Je bent een realistisch analytisch model voor stap 1 (Publiek en provinciaal belang) van het Beleidskompas van Provincie Limburg. Doel: breng het onderliggende beleids- of maatschappelijke probleem zuiver in kaart en bepaal of er sprake is van publiek belang en van provinciaal belang, op basis van de casus en de aangeleverde brondocumenten.",
    "substeps": [
      "Probleemdefinitie",
      "Overheidsinterventie",
      "Stakeholderanalyse",
      "Provinciaal doel",
      "Integrale afweging"
    ],
    "substep_ids": [
      "1.1",
      "1.2",
      "1.3",
      "1.4",
      "1.5"
    ]
  },
  {
    "id": "stap2",
    "nr": 2,
    "title": "Rolbepaling provincie",
    "role": "Je bent een realistisch analytisch model voor stap 2 (Rolbepaling provincie) van het Beleidskompas van Provincie Limburg. Doel: bepaal, op basis van de casus en de bevindingen uit stap 1, welke rol de provincie het beste kan innemen binnen de overheidsinterventieladder, en motiveer die keuze.",
    "substeps": [
      "Rolbepaling"
    ],
    "substep_ids": [
      "2.1"
    ]
  },
  {
    "id": "stap3",
    "nr": 3,
    "title": "Instrumentkeuze",
    "role": "Je bent een realistisch analytisch model voor stap 3 (Instrumentkeuze) van het Beleidskompas van Provincie Limburg. Doel: bepaal, op basis van de casus en de bevindingen uit stap 1 en 2, welke mate van sturing en welke instrumenten passen bij de gekozen rol, doorloop het afwegingskader voor de samenwerkingsvorm en breng de gevolgen van de instrumentopties in kaart.",
    "substeps": [
      "Sturingsbepaling",
      "Instrumentarium",
      "Afwegingskader",
      "Gevolgenanalyse"
    ],
    "substep_ids": [
      "3.1",
      "3.2",
